insert into public.admin_help_items(help_key,title_fa,body_fa,warning_fa,title_en,body_en,warning_en,active) values
('tax.settings','تنظیمات مالیات','مالیات برای هر سایت مستقل است و به‌صورت پیش‌فرض خاموش می‌ماند. می‌توان نرخ، حالت افزوده‌شونده یا داخل‌قیمت، اعمال روی ارسال و عنوان نمایشی را تنظیم کرد.','قوانین مالیاتی هر کشور و منطقه متفاوت است. RAVA فقط موتور محاسبه را فراهم می‌کند و نرخ/قانون باید توسط مدیر بر اساس الزامات واقعی کسب‌وکار تنظیم شود.','Tax settings','Tax is tenant-specific and disabled by default. Configure rate, exclusive/inclusive mode, whether shipping is taxable, and display labels.','Tax law varies by country and region. RAVA provides calculation infrastructure; the business must configure the correct legal rate and rules.',true)
insert into public.guidance_articles(article_key,area,route_prefix,title_fa,summary_fa,body_fa,title_en,summary_en,body_en,keywords,importance,related_help_keys,active,sort_order) values
('commerce.tax.guide','commerce','/admin/commerce/checkout','راهنمای مالیات فروشگاه','مالیات را فقط در صورت نیاز فعال کن','مالیات به‌صورت پیش‌فرض خاموش است. حالت Exclusive مالیات را پس از تخفیف به مبلغ سفارش اضافه می‌کند. حالت Inclusive مالیات را داخل قیمت محاسبه و فقط سهم مالیات را گزارش می‌کند. می‌توان تعیین کرد هزینه ارسال نیز مشمول مالیات باشد یا نه. تنظیم کشور/منطقه برای توسعه قواعد منطقه‌ای آینده ذخیره می‌شود.','Store Tax Guide','Enable tax only when needed','Tax is disabled by default. Exclusive mode adds tax after discounts. Inclusive mode treats tax as already included and reports the tax portion. Shipping taxation is optional. Country/region fields prepare the tenant for future jurisdiction-specific rules.',array['مالیات','tax','vat','sales tax','checkout'],'important',array['tax.settings'],true,42)
